validator:
function validate([secret, target]) {
  if (!Array.isArray(secret) || secret.length < 1 || secret.length > 10000) return 'secret needs 1 to 10^4 values.';
  if (secret.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value of secret is a whole number from -10^4 to 10^4.';
  for (let i = 1; i < secret.length; i++) if (secret[i - 1] >= secret[i]) return 'secret must be strictly increasing.';
  if (!Number.isInteger(target) || target < -10000 || target > 10000) return 'target is a whole number from -10^4 to 10^4.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [secret, target] = input;
  const limit = 64;
  let calls = 0;
  // The array is reachable only through get(); indexes outside it read as 2^31 - 1, like LeetCode's ArrayReader.
  const reader = {
    get(index) {
      if (!Number.isInteger(index)) throw new Error(`reader.get needs a whole-number index, not ${index}.`);
      calls++;
      if (calls > limit) throw new Error('reader.get was called more than 64 times; find the bounds and binary search in O(log n) calls.');
      return index >= 0 && index < secret.length ? secret[index] : 2147483647;
    },
  };
  const result = solve(reader, target);
  if (!Number.isInteger(result)) throw new Error('Return the index of target, or -1.');
  return result;
}

