function search(reader, target) {
  // Skip the doubling: the constraints cap the length at 10^4, so search indexes 0..9999 for the first value >= target.
  let low = 0;
  let high = 10000;
  while (low < high) {
    const middle = (low + high) >> 1;
    if (reader.get(middle) < target) low = middle + 1;
    else high = middle;
  }
  return low < 10000 && reader.get(low) === target ? low : -1;
}

