function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1500 + pick(501) : 1 + pick(10);
  const secret = [];
  let value = size === 'large' ? -10000 + pick(100) : -20 + pick(15);
  for (let i = 0; i < n; i++) {
    secret.push(value);
    value += 1 + pick(size === 'large' ? 9 : 4);
  }
  const roll = rand();
  // Usually a present value; sometimes a gap, or a value beyond either end.
  let target;
  if (roll < 0.5) target = secret[pick(n)];
  else if (roll < 0.7) target = secret[0] - 1 - pick(5);
  else if (roll < 0.85) target = secret[n - 1] + 1 + pick(5);
  else target = secret[0] + pick(secret[n - 1] - secret[0] + 1);
  return [secret, Math.max(-10000, Math.min(10000, target))];
}
